#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    int tupleSameProduct(vector<int>& nums) {
        unordered_map<int, int> freq;
        int n = nums.size();
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                freq[nums[i] * nums[j]]++;
            }
        }
        int ans = 0;
        for (const auto& [prod, count] : freq) {
            if (count > 1) {
                ans += 8 * (count * (count - 1) / 2);
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int tupleSameProduct(int[] nums) {
        Map<Integer, Integer> freq = new HashMap<>();
        int n = nums.length;
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int prod = nums[i] * nums[j];
                freq.put(prod, freq.getOrDefault(prod, 0) + 1);
            }
        }
        int ans = 0;
        for (int count : freq.values()) {
            if (count > 1) {
                ans += 8 * (count * (count - 1) / 2);
            }
        }
        return ans;
    }
}

