var tupleSameProduct = function(nums) {
    const freq = new Map();
    const n = nums.length;
    for (let i = 0; i < n; ++i) {
        for (let j = i + 1; j < n; ++j) {
            const prod = nums[i] * nums[j];
            freq.set(prod, (freq.get(prod) || 0) + 1);
        }
    }
    let ans = 0;
    for (const count of freq.values()) {
        if (count > 1) {
            ans += 8 * Math.floor(count * (count - 1) / 2);
        }
    }
    return ans;
};
